// ===== أدوات عامة وتخزين كبير في IndexedDB =====
function esc(s){return String(s==null?'':s).replace(/[&<>"']/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})}
function num(v){var n=Number(v);return isFinite(n)?n:0}
function money(v){return num(v).toLocaleString('ar-EG',{maximumFractionDigits:2})+' ج.م'}
function fmtDate(v){if(!v)return'';var p=String(v).slice(0,10).split('-');if(p.length!==3)return esc(v);return new Date(+p[0],+p[1]-1,+p[2]).toLocaleDateString('ar-EG',{day:'numeric',month:'short',year:'numeric'})}
function today(){var d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
function uid(){return'mf-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,10)}
function tempId(){return'tmp-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,7)}
function ago(ms){if(!ms)return'لسه';var m=Math.floor((Date.now()-ms)/60000);return m<1?'دلوقتي':m<60?'من '+m+' دقيقة':m<1440?'من '+Math.floor(m/60)+' ساعة':'من '+Math.floor(m/1440)+' يوم'}
function b64ToBytes(s){var b=atob(s),u=new Uint8Array(b.length);for(var i=0;i<b.length;i++)u[i]=b.charCodeAt(i);return u}
function bytesToB64(u){var s='';for(var i=0;i<u.length;i+=32768)s+=String.fromCharCode.apply(null,u.subarray(i,i+32768));return btoa(s)}
function hex(buf){return Array.prototype.map.call(new Uint8Array(buf),function(x){return(x<16?'0':'')+x.toString(16)}).join('')}
function normCode(c){return String(c||'').toUpperCase().replace(/[^A-Z0-9]/g,'')}
function lsGet(k){try{return localStorage.getItem('mz_'+k)}catch(e){return null}}
function lsSet(k,v){try{if(v==null)localStorage.removeItem('mz_'+k);else localStorage.setItem('mz_'+k,v)}catch(e){}}
var dbp=new Promise(function(resolve){if(!window.indexedDB)return resolve(null);var r=indexedDB.open('mizan-mobile-full',1);r.onupgradeneeded=function(){if(!r.result.objectStoreNames.contains('state'))r.result.createObjectStore('state')};r.onsuccess=function(){resolve(r.result)};r.onerror=function(){resolve(null)}});
async function kvGet(k,d){var db=await dbp;if(!db){try{var x=JSON.parse(lsGet(k)||'null');return x==null?d:x}catch(e){return d}}return new Promise(function(resolve){var r=db.transaction('state').objectStore('state').get(k);r.onsuccess=function(){resolve(r.result==null?d:r.result)};r.onerror=function(){resolve(d)}})}
async function kvSet(k,v){var db=await dbp;if(!db){if(v==null)lsSet(k,null);else lsSet(k,JSON.stringify(v instanceof Uint8Array?{u8:bytesToB64(v)}:v));return}return new Promise(function(resolve){var tx=db.transaction('state','readwrite');if(v==null)tx.objectStore('state').delete(k);else tx.objectStore('state').put(v,k);tx.oncomplete=resolve;tx.onerror=resolve})}
async function kvRaw(k){var v=await kvGet(k,null);if(v&&v.u8&&typeof v.u8==='string')return b64ToBytes(v.u8);return v}
async function kvClear(){var db=await dbp;try{Object.keys(localStorage).forEach(function(k){if(k.indexOf('mz_')===0)localStorage.removeItem(k)})}catch(e){}if(!db)return;return new Promise(function(resolve){var tx=db.transaction('state','readwrite');tx.objectStore('state').clear();tx.oncomplete=resolve;tx.onerror=resolve})}
// 2.3.3: كل البيانات المحلية متشفّرة بمفتاح DK، وDK نفسه متشفّر بمفتاح متولّد من الرمز (PBKDF2) — من غير الرمز مفيش فك
function gcmEnc(key,bytes){var iv=crypto.getRandomValues(new Uint8Array(12));return crypto.subtle.encrypt({name:'AES-GCM',iv:iv},key,bytes).then(function(c){var ct=new Uint8Array(c),o=new Uint8Array(12+ct.length);o.set(iv,0);o.set(ct,12);return o})}
function gcmDec(key,bytes){return crypto.subtle.decrypt({name:'AES-GCM',iv:bytes.subarray(0,12)},key,bytes.subarray(12)).then(function(p){return new Uint8Array(p)})}
async function sSet(k,v,raw){if(!DK)return;if(v==null)return kvSet(k,null);var b=raw?v:enc8.encode(JSON.stringify(v));return kvSet(k,await gcmEnc(DK,b))}
async function sGet(k,d,raw){var v=await kvRaw(k);if(v==null||!DK)return d;if(!(v instanceof Uint8Array))return raw?d:v;try{var p=await gcmDec(DK,v);return raw?p:JSON.parse(dec8.decode(p))}catch(e){return d}}
async function saveState(){if(!DK)return;await Promise.all([sSet('T',T),sSet('pack',pack),sSet('outbox',outbox),sSet('notes',notes.slice(-30)),sSet('downloads',downloads.slice(-50)),kvSet('last',lastSync)])}

// ===== التشفير والربط =====
function aesKey(raw){return crypto.subtle.importKey('raw',raw,'AES-GCM',false,['encrypt','decrypt'])}
function decrypt(rawKey,bytes,magic){if(bytes.length<32||dec8.decode(bytes.subarray(0,4))!==magic)return Promise.reject(new Error('صيغة بيانات غير معروفة'));return aesKey(rawKey).then(function(k){return crypto.subtle.decrypt({name:'AES-GCM',iv:bytes.subarray(4,16)},k,bytes.subarray(16))}).then(function(p){return new Uint8Array(p)})}
function encrypt(rawKey,bytes,magic){var iv=crypto.getRandomValues(new Uint8Array(12));return aesKey(rawKey).then(function(k){return crypto.subtle.encrypt({name:'AES-GCM',iv:iv},k,bytes)}).then(function(c){var ct=new Uint8Array(c),out=new Uint8Array(16+ct.length);out.set(enc8.encode(magic),0);out.set(iv,4);out.set(ct,16);return out})}
function relay(op,body){if(!CFG.relay||/RELAY_URL/.test(CFG.relay))return Promise.reject(new Error('رابط المزامنة غير مجهز'));body=body||{};body.op=op;return fetch(CFG.relay,{method:'POST',body:JSON.stringify(body),redirect:'follow',cache:'no-store'}).then(function(r){return r.json()}).then(function(j){if(!j||!j.ok){var e=new Error((j&&j.error)||'خدمة المزامنة لا تستجيب');e.code=j&&j.error;throw e}return j})}
function send(msg){return encrypt(b64ToBytes(T.k),enc8.encode(JSON.stringify(msg)),'MZM1').then(function(b){return relay('put',{box:T.b,data:bytesToB64(b)})})}
function fetchPack(){var get=CFG.apiKey?fetch('https://www.googleapis.com/drive/v3/files/'+encodeURIComponent(T.f)+'?alt=media&key='+encodeURIComponent(CFG.apiKey),{cache:'no-store'}).then(function(r){if(r.status===404)return{gone:true};if(!r.ok)throw new Error('درايف: '+r.status);return r.arrayBuffer().then(function(a){return{bytes:new Uint8Array(a)}})}):relay('pack',{f:T.f}).then(function(j){if(j.status===404)return{gone:true};if(j.status!==200)throw new Error('درايف: '+j.status);return{bytes:b64ToBytes(j.data)}});return get.then(function(r){if(r.gone)return r;return openPack(r.bytes)})}
// 3.0.0: MZP2 = هيدر + قاعدة SQLite كاملة (مضغوطة ومتشفّرة)
async function gunzip(u){return new Uint8Array(await new Response(new Blob([u]).stream().pipeThrough(new DecompressionStream('gzip'))).arrayBuffer())}
async function openPack(bytes){if(dec8.decode(bytes.subarray(0,4))==='MZP2'){var raw=await gunzip(await decrypt(b64ToBytes(T.k),bytes,'MZP2'));var n=new DataView(raw.buffer,raw.byteOffset).getUint32(0,true);var h=JSON.parse(dec8.decode(raw.subarray(4,4+n)));h.__db=raw.slice(4+n);return h}var p=await decrypt(b64ToBytes(T.k),bytes,'MZP1');return JSON.parse(dec8.decode(p))}
function validCode(code){var c=normCode(code);if(c.length!==9||c.split('').some(function(x){return ALPHA.indexOf(x)<0}))throw new Error('الكود لازم يكون 9 حروف وأرقام');return c}
// الرمز بيتعمل الأول وبعدين الكود يتسحب — كده مفتاح المكتب عمره مايتخزن من غير تشفير
async function pair(code,pin){var c=validCode(code);var tk;try{var k=await crypto.subtle.importKey('raw',enc8.encode(c),'PBKDF2',false,['deriveBits']);var bits=await crypto.subtle.deriveBits({name:'PBKDF2',salt:enc8.encode('mizan-ticket-v1'),iterations:300000,hash:'SHA-256'},k,512);var b=new Uint8Array(bits);tk=b.slice(32);var j=await relay('claim',{id:hex(b.slice(0,32))});var p=await decrypt(tk,b64ToBytes(j.blob),'MZT1');var t=JSON.parse(dec8.decode(p));await kvClear();await createLock(pin);T=t;pack=null;outbox=[];notes=[];downloads=[];lastSync=0;await saveState();lastAct=Date.now();await send({t:'hello',ua:navigator.userAgent.slice(0,120),at:Date.now(),v:APP_V,full:1}).then(function(){T.h3=1;return saveState()}).catch(function(){});await sync(true)}catch(e){if(e.code==='expired')throw new Error('الكود خلص أو اتستخدم قبل كده؛ اطلب كود جديد');if(e.message==='Failed to fetch')throw new Error('مفيش إنترنت');throw e}}
async function wipe(msg){if(window.MZFull)await MZFull.wipe();await kvClear();T=null;pack=null;outbox=[];notes=[];downloads=[];lastSync=0;DK=null;heldDK=null;renderPair('',msg)}

// ===== عمليات Offline-first =====
function basePerm(p){return!!(pack&&pack.permissions&&(pack.permissions.indexOf('*')>=0||pack.permissions.indexOf(p)>=0))}
// صلاحيات الموبايل نفسه (من «موبايلات المحامين») فوق صلاحيات المستخدم — دايمًا أقل أو زيها
function mAccess(){var m=pack&&pack.mobile;return m&&m.access||'full'}
function can(p){if(!basePerm(p))return false;if(/^(users\.manage|settings\.manage)$/.test(p)&&!(basePerm('*')&&mAccess()==='full'))return false;if(/\.(write|delete)$/.test(p)&&mAccess()!=='full')return false;if(p==='docs.write'&&pack.mobile&&!pack.mobile.up)return false;return true}
function canDecide(){return basePerm('hearings.write')&&mAccess()!=='view'}
function canDownload(){return basePerm('docs.read')&&!(pack&&pack.mobile&&!pack.mobile.down)}
function canAdminView(){return basePerm('*')}
var ACCESS_NAMES={view:'عرض بس',decisions:'عرض وتسجيل قرارات الجلسات',full:'كامل'};
function localValue(v){if(typeof v==='string'&&v.charAt(0)==='@')return v.slice(1);if(Array.isArray(v))return v.map(localValue);if(v&&typeof v==='object'){var o={};Object.keys(v).forEach(function(k){o[k]=localValue(v[k])});return o}return v}
function remoteBody(body){var o={};Object.keys(body||{}).forEach(function(k){var v=body[k];if(/_id$/.test(k)&&typeof v==='string'&&v.indexOf('tmp-')===0)o[k]='@'+v;else o[k]=v});return o}
function remoteId(id){return typeof id==='string'&&id.indexOf('tmp-')===0?'@'+id:String(id)}
function collFor(path){if(/^\/api\/cases\/[^/]+\/stages$/.test(path)||/^\/api\/stages\//.test(path))return'case_stages';if(/^\/api\/clients\/[^/]+\/poas$/.test(path)||/^\/api\/poas/.test(path))return'poas';var m=/^\/api\/(clients|cases|hearings|appointments|tasks|documents|payments|deadlines|adminwork|notices|secretaries|templates|users)/.exec(path);if(!m)return null;return{secretaries:'session_secretaries'}[m[1]]||m[1]}
function pathId(path){var p=path.split('/').filter(Boolean),x=p[p.length-1];if(['decision','status','done','received','current','restore','stages','poas','password'].indexOf(x)>=0)x=p[p.length-2];x=String(x||'').replace(/^@/,'');return/^\d+$/.test(x)?Number(x):x}
function optimistic(target,it){if(!target||it.op!=='mutate')return target;var path=it.path.replace(/\/@/g,'/'),coll=collFor(path);if(!coll||!Array.isArray(target[coll]))return target;var a=target[coll],id=pathId(path),body=localValue(it.body||{}),method=it.method;
  if(/\/decision$/.test(path)){var h=a.find(function(x){return String(x.id)===String(id)});if(h){h.decision=body.decision;h.done=1;h._pending=1}return target}
  if(/\/(status|done|received|current)$/.test(path)){var r=a.find(function(x){return String(x.id)===String(id)});if(r){Object.assign(r,body);r._pending=1}return target}
  if(method==='DELETE'){target[coll]=a.filter(function(x){return String(x.id)!==String(id)});return target}
  if(method==='PUT'){var row=a.find(function(x){return String(x.id)===String(id)});if(row){Object.assign(row,body);row._pending=1}return target}
  if(method==='POST'){var row2=Object.assign({id:it.temp||tempId(),created_at:new Date().toISOString(),_pending:1},body);if(coll==='case_stages'&&!row2.case_id){var cm=/\/cases\/([^/]+)\/stages/.exec(path);if(cm)row2.case_id=cm[1].replace(/^@/,'')}a.unshift(row2)}return target}
async function enqueueMutation(method,path,body,temp){var it={uid:uid(),op:'mutate',method:method,path:path,body:remoteBody(body||{})};if(temp)it.temp=temp;outbox.push(it);optimistic(pack,it);await saveState();render();sync(false)}
async function enqueueDownload(id){if(!canDownload())return note('الموبايل ده مش مسموحله ينزّل مستندات','red');var have=downloads.find(function(x){return String(x.document_id)===String(id)});if(have)return openDownload(have);if(outbox.some(function(o){return o.op==='file_download'&&String(o.document_id)===String(id)}))return note('طلب التنزيل متسجل بالفعل');outbox.push({uid:uid(),op:'file_download',document_id:Number(id)});await saveState();note('طلب تنزيل المستند اتسجل؛ هينزل أول ما الكمبيوتر يرد','green');sync(true)}
function applyPending(p){outbox.forEach(function(x){if(x.op==='mutate')optimistic(p,x);else if(x.op==='decision')optimistic(p,{op:'mutate',method:'POST',path:'/api/hearings/'+x.hearing_id+'/decision',body:{decision:x.decision}});else if(x.op==='upload'&&Array.isArray(p.documents)&&!p.documents.some(function(d){return d._up===x.uid}))p.documents.unshift({id:x.meta.temp||x.uid,_up:x.uid,_pending:1,title:x.meta.title,filename:x.meta.filename,size:x.size,case_id:String(x.meta.case_id||'').replace(/^@/,'')||null,client_id:String(x.meta.client_id||'').replace(/^@/,'')||null})});return p}
function b64(u){u=u instanceof Uint8Array?u:new Uint8Array(u);var s='',i;for(i=0;i<u.length;i+=32768)s+=String.fromCharCode.apply(null,u.subarray(i,i+32768));return btoa(s)}
// 3.1.0: جوه تطبيق ميزان أندرويد — الملف بيتحفظ في التنزيلات/Mizan وبتفتح قايمة المشاركة (المتصفح العادي مش بيتأثر)
function saveBlob(bytes,name,mime){if(window.MizanAndroid&&window.MizanAndroid.save){try{var r=String(window.MizanAndroid.save(name||'document',mime||'application/octet-stream',b64(bytes)));if(r==='ok')return;if(r.indexOf('old:')===0){note('الملف اتحفظ على الموبايل: '+r.slice(4),'green');return}}catch(e){}}saveBlob0(bytes,name,mime)}
function saveBlob0(bytes,name,mime){var blob=new Blob([bytes],{type:mime||'application/octet-stream'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name||'document';document.body.appendChild(a);a.click();a.remove();setTimeout(function(){URL.revokeObjectURL(a.href)},30000)}
async function openDownload(d){var b=await sGet('dl:'+d.document_id,null,true);if(!b){downloads=downloads.filter(function(x){return x!==d});await saveState();return note('الملف مش موجود على الموبايل؛ نزّله تاني','red')}saveBlob(b,d.filename,d.mime)}
async function removeDownload(id){downloads=downloads.filter(function(x){return String(x.document_id)!==String(id)});await kvSet('dl:'+id,null);await saveState();render()}

// ===== المزامنة: كل عملية لوحدها، والنسخة الجديدة بتتسحب دايمًا، والملفات في الآخر =====
function isNet(e){return/Failed to fetch|NetworkError|network|Load failed/i.test(String(e&&e.message||''))}
function isFull(e){return e&&e.code==='box full'}
function wire(o){var x={};['uid','op','method','path','body','temp','hearing_id','decision','next_date','next_time','document_id'].forEach(function(k){if(o[k]!==undefined)x[k]=o[k]});return x}
function due(o,force){if(o.failed||o.op==='upload'||o.op==='fetch')return false;if(force||!o.sent)return true;var wait=Math.min(RESEND_MS*Math.pow(2,Math.max(0,(o.sends||1)-1)),RESEND_MAX);return Date.now()-o.sent>wait}
var RELAY_ERR={'bad message':'صندوق المزامنة رفض الرسالة (حجمها كبير أو بايظة)','box full':'صندوق المزامنة مليان','bad id':'رقم غير صالح','unknown op':'نسخة صندوق المزامنة قديمة'};
function failOp(o,e){o.tries=(o.tries||0)+1;o.err=RELAY_ERR[e&&e.code]||(e&&e.message)||'خطأ';if(o.tries>=MAX_TRIES)o.failed=true}
async function sendItems(force){var list=outbox.filter(function(o){return due(o,force)}),batch=[],size=0;
  async function one(b){await send({t:'items',items:b.map(wire)});var now=Date.now();b.forEach(function(o){o.sent=now;o.sends=(o.sends||0)+1;o.tries=0;o.err=''})}
  async function flush(){if(!batch.length)return;var b=batch;batch=[];size=0;try{await one(b)}catch(e){if(isNet(e)||isFull(e))throw e;
    // دفعة اترفضت ⇒ كل عملية تتجرب لوحدها، واللي فيها مشكلة بس هي اللي تتحسب عليها
    for(var i=0;i<b.length;i++){try{await one([b[i]])}catch(e2){if(isNet(e2)||isFull(e2))throw e2;failOp(b[i],e2)}}}}
  for(var i=0;i<list.length;i++){var sz=JSON.stringify(wire(list[i])).length;if(batch.length&&(size+sz>BATCH_MAX||batch.length>=25))await flush();batch.push(list[i]);size+=sz}
  await flush()}
async function applyResults(np){var by={};(np.results||[]).forEach(function(r){by[r.uid]=r});var ack=[],keep=[];
  for(var i=0;i<outbox.length;i++){var o=outbox[i],r=by[o.uid];if(!r||o.op==='fetch'){keep.push(o);continue}ack.push(o.uid);
    if(r.retry){o.sent=Date.now()-RESEND_MS+60000;o.sends=0;keep.push(o);continue}
    if(r.partial&&o.op==='upload'){o.resend=(r.missing||[]).filter(function(i){return i>=0&&i<o.n});o.doneAt=0;o.err=r.error||'';keep.push(o);continue}
    if(!r.ok){notes.push({type:'red',text:'ماتحفظش في المكتب: '+(r.error||'خطأ')+(o.op==='upload'?' ('+o.meta.filename+')':'')});if(o.op==='upload')await kvSet('f:'+o.uid,null);continue}
    if(o.op==='upload'){await kvSet('f:'+o.uid,null);notes.push({type:'green',text:'المستند وصل المكتب: '+o.meta.filename});continue}
    if(r.file&&r.file.f){keep.push({uid:'fx-'+o.uid,op:'fetch',file:r.file});continue}
    if(r.file&&r.file.data){await storeDownload(r.file,b64ToBytes(r.file.data));continue}
    if(r.file&&r.file.stale){notes.push({type:'red',text:'اطلب تنزيل '+(r.file.filename||'المستند')+' تاني'});continue}
    if(r.conflict)notes.push({type:'',text:'حدث تعارض؛ تم حفظ تعديل الهاتف في الملاحظات'})}
  outbox=keep;if(ack.length)send({t:'result_ack',uids:ack}).catch(function(){})}
async function storeDownload(f,bytes){await sSet('dl:'+f.document_id,bytes,true);downloads=downloads.filter(function(x){return String(x.document_id)!==String(f.document_id)});downloads.push({document_id:f.document_id,filename:f.filename,mime:f.mime,size:bytes.length,at:Date.now()});notes.push({type:'green',text:'نزل '+f.filename+' — دوس «فتح» من المستندات'})}
function fetchBlob(f){var get=CFG.apiKey?fetch('https://www.googleapis.com/drive/v3/files/'+encodeURIComponent(f)+'?alt=media&key='+encodeURIComponent(CFG.apiKey),{cache:'no-store'}).then(function(r){if(r.status===404)return null;if(!r.ok)throw new Error('درايف: '+r.status);return r.arrayBuffer().then(function(a){return new Uint8Array(a)})}):relay('pack',{f:f}).then(function(j){if(j.status===404)return null;if(j.status!==200)throw new Error('درايف: '+j.status);return b64ToBytes(j.data)});return get}
async function runFetches(){var list=outbox.filter(function(o){return o.op==='fetch'&&!o.failed});for(var i=0;i<list.length;i++){var o=list[i];try{var enc=await fetchBlob(o.file.f);if(!enc){outbox=outbox.filter(function(x){return x!==o});notes.push({type:'red',text:'الملف المؤقت اتمسح قبل ما ينزل؛ اطلب '+o.file.filename+' تاني'});continue}var bytes=await decrypt(b64ToBytes(T.k),enc,'MZF1');await storeDownload(o.file,bytes);outbox=outbox.filter(function(x){return x!==o});send({t:'file_ack',f:o.file.f}).catch(function(){})}catch(e){if(isNet(e))throw e;failOp(o,e)}await saveState()}}
function upLeft(o){return o.resend&&o.resend.length?o.resend.length:Math.max(0,o.n-(o.next||0))}
function upPct(o){return Math.round(100*(o.n-upLeft(o))/o.n)}
async function runUploads(){var caps=pack&&pack.caps;var list=outbox.filter(function(o){return o.op==='upload'&&!o.failed});
  for(var k=0;k<list.length;k++){var o=list[k];if(!caps||!caps.chunks){o.err='حدّث ميزان على الكمبيوتر لـ 2.3.3 عشان يستقبل الملفات من الموبايل';continue}
    var idx=o.resend&&o.resend.length?o.resend.slice():[];if(!idx.length)for(var i=o.next||0;i<o.n;i++)idx.push(i);
    if(!idx.length){if(o.doneAt&&Date.now()-o.doneAt>UPLOAD_WAIT){o.failed=true;o.err='ماوصلش رد من المكتب'}continue}
    var bytes=await sGet('f:'+o.uid,null,true);if(!bytes){o.failed=true;o.err='الملف مش موجود على الموبايل';continue}
    var cs=o.chunk||CHUNK;uploading=o.uid;
    for(var j=0;j<idx.length;j++){if(!DK||!T)return;var n=idx[j],m={t:'chunk',fid:o.uid,i:n,n:o.n,sha256:o.sha,data:bytesToB64(bytes.subarray(n*cs,(n+1)*cs))};if(n===0)m.meta=o.meta;
      try{await send(m)}catch(e){if(isNet(e)||isFull(e))throw e;failOp(o,e);break}
      o.tries=0;o.err='';if(o.resend&&o.resend.length)o.resend=o.resend.filter(function(x){return x!==n});else o.next=n+1;
      if(j%4===3||j===idx.length-1){await saveState();renderProgress(o)}}
    if(!upLeft(o))o.doneAt=Date.now()}
  uploading=null}
async function sync(force){if(!T||!DK||syncing)return;if(T.standalone){if(window.MZFull)MZFull.soloSync(force);return}syncing=true;syncErr='';render();var down=false;
  try{await sendItems(force)}catch(e){down=isNet(e);syncErr=down?'مفيش إنترنت':isFull(e)?'صندوق المزامنة مليان — مستني كمبيوتر المكتب يستلم':e.message}
  await saveState();
  try{var np=await fetchPack();if(!DK){syncing=false;return}if(np.gone){syncing=false;await wipe('المكتب ألغى ربط الجهاز');return}if(np.wipe){syncing=false;await wipe('مدير المكتب أوقف نسخة الموبايل للحساب');return}
    await applyResults(np);notes.forEach(function(n){if(!n.at)n.at=Date.now()});if(np.__db){var dbb=np.__db;delete np.__db;await sSet('db',dbb,true);pack=np;if(window.MZFull)MZFull.onDb(dbb)}else pack=applyPending(np);lastSync=Date.now();notes=notes.slice(-30);await saveState()}catch(e){if(!syncErr)syncErr=isNet(e)?'مفيش إنترنت':e.message;down=down||isNet(e)}
  if(!down&&DK){try{await runFetches();await runUploads()}catch(e){if(!syncErr)syncErr=isNet(e)?'مفيش إنترنت':isFull(e)?'صندوق المزامنة مليان — مستني كمبيوتر المكتب يستلم':e.message}uploading=null;await saveState()}
  syncing=false;if(DK)render()}
function renderProgress(o){var el=document.querySelector('[data-prog="'+o.uid+'"]');if(el){el.querySelector('i').style.width=upPct(o)+'%';el.querySelector('span').textContent=upPct(o)+'%'}}
async function retryOp(id){var o=outbox.find(function(x){return x.uid===id});if(!o)return;o.failed=false;o.tries=0;o.err='';o.sent=0;o.sends=0;if(o.op==='upload'&&!upLeft(o)){o.next=0;o.resend=[];o.doneAt=0}await saveState();render();sync(true)}
async function cancelOp(id){var o=outbox.find(function(x){return x.uid===id});if(!o)return;if(!confirm('إلغاء العملية دي؟ مش هتوصل المكتب.'))return;outbox=outbox.filter(function(x){return x!==o});if(o.op==='upload'){await kvSet('f:'+o.uid,null);if(pack&&pack.documents)pack.documents=pack.documents.filter(function(d){return d._up!==o.uid})}await saveState();render();sync(true)}
function note(text,type){notes.push({type:type||'',text:text,at:Date.now()});notes=notes.slice(-30);saveState();render()}

// ===== مكوّنات الواجهة =====
function statusPill(s){var c=/منته|تم|صدر حكم|ساري/.test(s||'')?'green':/متأخر|ملغي|موقوف|مشطوب/.test(s||'')?'red':/جديدة|متداولة|قائمة/.test(s||'')?'blue':'';return'<span class="pill '+c+'">'+esc(s||'—')+'</span>'}
function header(){var who=pack?(pack.user||((pack.me||{}).full_name)):T.u,st=syncing?'جاري التحديث…':syncErr?syncErr:'آخر مزامنة '+ago(lastSync);return'<header class="topbar"><img class="brandmark" src="icon-192.png"><div class="top-title"><b>ميزان موبايل</b><small>'+esc(who||'')+' · '+esc(st)+(outbox.length?' <span class="pending-dot'+(outbox.some(function(o){return o.failed})?' red':'')+'">'+outbox.length+'</span>':'')+'</small></div><button class="icon-btn" data-sync aria-label="مزامنة">↻</button></header>'}
function nav(){var n=[['home','⌂','الرئيسية'],['hearings','◫','الجلسات'],['cases','⚖','القضايا'],['clients','♟','الموكلون'],['more','•••','المزيد']];return'<nav class="bottom-nav">'+n.map(function(x){return'<button data-page="'+x[0]+'" class="'+(page===x[0]?'on':'')+'"><b>'+x[1]+'</b>'+x[2]+'</button>'}).join('')+'</nav>'}
function head(title,add,back){return'<div class="page-head">'+(back?'<button class="back" data-back>رجوع</button>':'')+'<h1>'+esc(title)+'</h1>'+(add?'<button class="primary sm" data-add="'+add+'">＋ إضافة</button>':'')+'</div>'}
function empty(t,s){return'<div class="empty"><b>'+esc(t)+'</b>'+esc(s||'')+'</div>'}
function searchBox(ph){return'<div class="search"><input data-search placeholder="'+esc(ph||'بحث')+'" value="'+esc(q)+'"></div>'}
// الإشعارات الخضرا بتختفي لوحدها بعد دقيقتين؛ الحمرا بتفضل لحد ما تتخفى
function noteList(){var now=Date.now();return notes.map(function(n,i){return[n,i]}).filter(function(x){return!(x[0].type==='green'&&x[0].at&&now-x[0].at>120000)}).reverse().map(function(x){var n=x[0];return'<div class="note '+esc(n.type||'')+'">'+esc(n.text)+' <a href="#" data-note="'+x[1]+'">إخفاء</a></div>'}).join('')}
function caseNo(c){return c.case_number?c.case_number+(c.case_year?' لسنة '+c.case_year:''):'بدون رقم'}
function getBy(coll,id){return((pack&&pack[coll])||[]).find(function(x){return String(x.id)===String(id)})}
function matches(x){if(!q)return true;var s=Object.keys(x||{}).map(function(k){return typeof x[k]==='string'?x[k]:''}).join(' ').toLowerCase();return s.indexOf(q.toLowerCase())>=0}

function homePage(){var t=today(),hs=(pack.hearings||[]).filter(function(x){return x.date===t}),tasks=(pack.tasks||[]).filter(function(x){return x.status!=='منجزة'}),dls=(pack.deadlines||[]).filter(function(x){return!x.done&&x.due_date>=t}).sort(function(a,b){return a.due_date.localeCompare(b.due_date)});var upcoming=(pack.hearings||[]).filter(function(x){return x.date>=t&&!x.done}).sort(function(a,b){return(a.date+(a.time||'')).localeCompare(b.date+(b.time||''))}).slice(0,5);var failed=outbox.filter(function(o){return o.failed}).length;return head('الرئيسية')+(failed?'<div class="note red">'+failed+' عملية ماوصلتش المكتب. <a href="#" data-page="sync">شوفها</a></div>':'')+(mAccess()!=='full'?'<div class="note">الموبايل ده: '+esc(ACCESS_NAMES[mAccess()])+'</div>':'')+'<div class="metrics"><div class="metric gold"><b>'+hs.length+'</b><span>جلسات اليوم</span></div><div class="metric blue"><b>'+tasks.length+'</b><span>مهام مفتوحة</span></div><div class="metric green"><b>'+dls.length+'</b><span>مواعيد قانونية</span></div></div><div class="section-title"><h2>جلسات اليوم والقادمة</h2><button data-page="hearings">عرض الكل</button></div>'+(upcoming.length?upcoming.map(hearingCard).join(''):empty('لا توجد جلسات قادمة'))+'<div class="section-title"><h2>المهام المطلوبة</h2><button data-page="tasks">عرض الكل</button></div>'+(tasks.length?tasks.slice(0,4).map(taskCard).join(''):empty('لا توجد مهام مفتوحة'))}
function caseCard(c){return'<div class="card clickable '+(c._pending?'pending':'')+'" data-open-case="'+esc(c.id)+'"><div class="card-row"><div class="card-main"><h3>'+esc(c.subject)+statusPill(c.status)+'</h3><div class="meta">'+esc(caseNo(c))+' · '+esc(c.degree||'')+'<br>'+esc(c.court||'')+(c.circuit?' — '+esc(c.circuit):'')+'<br>الموكل: '+esc(c.client_name||nameOf('clients',c.client_id))+'</div></div><span>‹</span></div></div>'}
function casesPage(){var a=(pack.cases||[]).filter(matches);return head('القضايا',can('cases.write')?'cases':null)+searchBox('ابحث برقم القضية أو الموكل أو المحكمة')+(a.length?a.map(caseCard).join(''):empty('لا توجد قضايا'))}
function hearingCard(h){var c=getBy('cases',h.case_id)||{};return'<div class="card '+(h._pending?'pending':'')+'"><div class="card-row"><div class="card-main"><h3>'+esc(h.date===today()?'اليوم':fmtDate(h.date))+(h.time?' <span class="pill">'+esc(h.time)+'</span>':'')+(h.done?'<span class="pill green">تم القرار</span>':'')+'</h3><div class="meta">'+esc(c.subject||'')+' · '+esc(h.stage_degree||c.degree||'')+' '+esc(h.stage_number||caseNo(c))+'<br>'+esc(h.stage_court||c.court||'')+(h.purpose?'<br>'+esc(h.purpose):'')+(h.decision?'<br><b>القرار:</b> '+esc(h.decision):'')+'</div></div></div><div class="actions">'+(!h.done&&canDecide()?'<button class="primary sm" data-decision="'+h.id+'">تسجيل القرار</button>':'')+'<button class="secondary sm" data-open-case="'+esc(h.case_id)+'">فتح القضية</button>'+(can('hearings.write')?'<button class="secondary sm" data-edit="hearings:'+esc(h.id)+'">تعديل</button>':'')+(can('hearings.delete')?'<button class="danger sm" data-delete="hearings:'+esc(h.id)+'">حذف</button>':'')+'</div></div>'}
function hearingsPage(){var a=(pack.hearings||[]).filter(matches).sort(function(a,b){return(b.date+(b.time||'')).localeCompare(a.date+(a.time||''))});return head('الجلسات والرول',can('hearings.write')?'hearings':null)+searchBox('ابحث في الجلسات')+(a.length?a.map(hearingCard).join(''):empty('لا توجد جلسات'))}
function clientCard(c){var count=(pack.cases||[]).filter(function(x){return String(x.client_id)===String(c.id)}).length;return'<div class="card clickable '+(c._pending?'pending':'')+'" data-open-client="'+esc(c.id)+'"><div class="card-row"><div class="card-main"><h3>'+esc(c.name)+'</h3><div class="meta">'+esc(c.kind||'')+(c.phone?' · '+esc(c.phone):'')+'<br>'+count+' قضية</div></div><span>‹</span></div></div>'}
function clientsPage(){var a=(pack.clients||[]).filter(matches);return head('الموكلون',can('clients.write')?'clients':null)+searchBox('ابحث باسم الموكل أو الهاتف')+(a.length?a.map(clientCard).join(''):empty('لا يوجد موكلون'))}
function taskCard(t){return'<div class="card '+(t._pending?'pending':'')+'"><div class="card-row"><div class="card-main"><h3>'+esc(t.title)+statusPill(t.status)+'</h3><div class="meta">'+esc(t.case_subject||nameOf('cases',t.case_id,'subject'))+(t.due_date?'<br>الموعد: '+fmtDate(t.due_date):'')+(t.assignee_name?'<br>المسؤول: '+esc(t.assignee_name):'')+'</div></div></div><div class="actions">'+(can('tasks.write')?'<button class="secondary sm" data-edit="tasks:'+esc(t.id)+'">تعديل</button>':'')+(can('tasks.write')&&t.status!=='منجزة'?'<button class="primary sm" data-task-done="'+esc(t.id)+'">تمت</button>':'')+(can('tasks.delete')?'<button class="danger sm" data-delete="tasks:'+esc(t.id)+'">حذف</button>':'')+'</div></div>'}
function tasksPage(){var a=(pack.tasks||[]).filter(matches);return head('المهام',can('tasks.write')?'tasks':null)+searchBox('بحث في المهام')+(a.length?a.map(taskCard).join(''):empty('لا توجد مهام'))}
function paymentCard(p){return'<div class="card '+(p._pending?'pending':'')+'"><div class="card-row"><div class="card-main"><h3>'+esc(p.kind)+' · '+fmtDate(p.date)+'</h3><div class="meta">'+esc(p.client_name||nameOf('clients',p.client_id))+(p.case_subject?'<br>'+esc(p.case_subject):'')+(p.description?'<br>'+esc(p.description):'')+'</div></div><span class="amount '+(p.kind==='مصروفات'?'out':'')+'">'+money(p.amount)+'</span></div><div class="actions">'+(can('finance.write')?'<button class="secondary sm" data-edit="payments:'+p.id+'">تعديل</button>':'')+(can('finance.delete')?'<button class="danger sm" data-delete="payments:'+p.id+'">حذف</button>':'')+'</div></div>'}
function financePage(){var a=(pack.payments||[]).filter(matches),fees=a.filter(function(x){return x.kind==='أتعاب'}).reduce(function(s,x){return s+num(x.amount)},0),exp=a.filter(function(x){return x.kind==='مصروفات'}).reduce(function(s,x){return s+num(x.amount)},0);return head('الحسابات',can('finance.write')?'payments':null)+'<div class="metrics"><div class="metric green"><b>'+money(fees)+'</b><span>المحصل</span></div><div class="metric gold"><b>'+money(exp)+'</b><span>المصروفات</span></div><div class="metric blue"><b>'+money(fees-exp)+'</b><span>الصافي</span></div></div>'+searchBox('بحث في الحسابات')+(a.length?a.map(paymentCard).join(''):empty('لا توجد عمليات مالية'))}
function documentCard(d){var up=d._up&&outbox.find(function(o){return o.uid===d._up}),dl=downloads.find(function(x){return String(x.document_id)===String(d.id)}),wait=outbox.some(function(o){return(o.op==='file_download'&&String(o.document_id)===String(d.id))||(o.op==='fetch'&&String(o.file.document_id)===String(d.id))});
  var acts=up?(up.failed?'<span class="pill red">ماوصلش</span><button class="primary sm" data-retry="'+esc(up.uid)+'">إعادة المحاولة</button><button class="danger sm" data-cancel="'+esc(up.uid)+'">إلغاء</button>':'<div class="upbar" data-prog="'+esc(up.uid)+'"><i style="width:'+upPct(up)+'%"></i><span>'+upPct(up)+'%</span></div><small class="muted">'+(upLeft(up)?(uploading===up.uid?'جاري الرفع…':'مستني المزامنة'):'اترفع — مستني تأكيد المكتب')+(up.err?' · '+esc(up.err):'')+'</small>')
    :(dl?'<button class="primary sm" data-open-dl="'+esc(d.id)+'">فتح</button><button class="secondary sm" data-rm-dl="'+esc(d.id)+'">مسح من الموبايل</button>':wait?'<span class="pill">جاري التنزيل…</span>':canDownload()&&!d._pending?'<button class="primary sm" data-download="'+esc(d.id)+'">تنزيل</button>':'')+(can('docs.delete')&&!d._pending?'<button class="danger sm" data-delete="documents:'+esc(d.id)+'">حذف</button>':'');
  return'<div class="card '+(d._pending?'pending':'')+'"><div class="card-row"><div class="card-main"><h3>📄 '+esc(d.title||d.filename)+'</h3><div class="meta">'+esc(d.filename||'')+' · '+(num(d.size)/1024/1024).toFixed(1)+' م.ب'+(d.case_subject?'<br>'+esc(d.case_subject):'')+'</div></div></div><div class="actions">'+acts+'</div></div>'}
function documentsPage(){var a=(pack.documents||[]).filter(matches);return head('المستندات',can('docs.write')?'documents':null)+searchBox('بحث باسم الملف أو القضية')+(a.length?a.map(documentCard).join(''):empty('لا توجد مستندات'))}
function genericCard(kind,x){var title='',meta='';if(kind==='appointments'){title=x.title;meta=fmtDate(x.date)+(x.time?' · '+x.time:'')+(x.place?'<br>'+esc(x.place):'')}else if(kind==='poas'){title='توكيل '+(x.number||'');meta=esc(x.client_name||nameOf('clients',x.client_id))+(x.office?'<br>'+esc(x.office):'')+(x.expires?'<br>ينتهي '+fmtDate(x.expires):'')}else if(kind==='deadlines'){title=x.kind;meta=fmtDate(x.due_date)+' · '+esc(nameOf('cases',x.case_id,'subject'))}else if(kind==='admin_work'){title=x.description;meta=esc(x.court||'')+(x.work_date?'<br>'+fmtDate(x.work_date):'')}else if(kind==='notices'){title='إعلان رقم '+(x.notice_no||'');meta=esc(x.bailiff_office||'')+(x.hearing_date?'<br>جلسة '+fmtDate(x.hearing_date):'')}else if(kind==='session_secretaries'){title=x.secretary_name;meta=esc(x.court||'')+(x.circuit?' — '+esc(x.circuit):'')+(x.phone?'<br>'+esc(x.phone):'')}else if(kind==='templates'){title=x.title;meta=esc(x.category||'')+(x.description?'<br>'+esc(x.description):'')}else if(kind==='users'){title=x.full_name;meta=esc(x.username||'')+' · '+roleName(x.role)+(x.active?'':' · موقوف')}else if(kind==='trash'){title=x.title||x.kind;meta=fmtDate(x.deleted_at)}return'<div class="card '+(x._pending?'pending':'')+'"><div class="card-main"><h3>'+esc(title)+((x.status||x.state)?statusPill(x.status||x.state):'')+'</h3><div class="meta">'+meta+'</div></div><div class="actions">'+editActions(kind,x)+'</div></div>'}
var GENERIC={appointments:['مواعيد المكتب','appts'],poas:['التوكيلات','poas'],deadlines:['المواعيد القانونية','deadlines'],admin_work:['شغل إداري','adminwork'],notices:['المحضرون','notices'],session_secretaries:['سكرتارية الجلسات','secretaries'],templates:['النماذج القانونية','templates'],users:['فريق المكتب','users'],trash:['سلة المحذوفات',null]};
function editActions(kind,x){if(kind==='trash')return mAccess()==='full'?'<button class="primary sm" data-restore="'+x.id+'">استرجاع</button>':'';var perm=GENERIC[kind][1],s='';if(kind==='users'){if(can('users.manage'))s+='<button class="secondary sm" data-edit="'+kind+':'+esc(x.id)+'">تعديل</button>';return s}if(can(perm+'.write'))s+='<button class="secondary sm" data-edit="'+kind+':'+esc(x.id)+'">تعديل</button>';if(can(perm+'.delete'))s+='<button class="danger sm" data-delete="'+kind+':'+esc(x.id)+'">حذف</button>';return s}
function genericPage(kind){var def=GENERIC[kind],a=(pack[kind]||[]).filter(matches),add=def[1]&&can(def[1]+'.write')?kind:null;if(kind==='users')add=can('users.manage')?kind:null;return head(def[0],add)+(kind==='users'&&!can('users.manage')?'<div class="note">إضافة وتعديل المستخدمين وكلمات السر لمدير المكتب بس.</div>':'')+searchBox('بحث')+(a.length?a.map(function(x){return genericCard(kind,x)}).join(''):empty('لا توجد بيانات'))}
function morePage(){var items=[['tasks','✓','المهام','tasks.read'],['appointments','◷','المواعيد','appts.read'],['documents','▤','المستندات','docs.read'],['finance','¤','الحسابات','finance.read'],['poas','▧','التوكيلات','poas.read'],['deadlines','⌛','المواعيد القانونية','deadlines.read'],['admin_work','☷','شغل إداري','adminwork.read'],['notices','➤','المحضرون','notices.read'],['session_secretaries','☎','سكرتارية الجلسات','secretaries.read'],['templates','✎','النماذج القانونية','templates.read'],['users','♟','فريق المكتب','*'],['trash','♲','سلة المحذوفات','*'],['sync','↻','المزامنة',null],['settings','⚙','الإعدادات',null]];return head('المزيد')+'<div class="more-grid">'+items.filter(function(x){return!x[3]||basePerm(x[3])}).map(function(x){return'<button class="menu-tile" data-page="'+x[0]+'"><b>'+x[1]+'</b><span>'+x[2]+'</span></button>'}).join('')+'</div>'}
function opTitle(o){if(o.op==='upload')return'رفع '+(o.meta.filename||'مستند');if(o.op==='fetch')return'تنزيل '+(o.file.filename||'مستند');if(o.op==='file_download'){var d=getBy('documents',o.document_id);return'طلب تنزيل '+(d?d.filename||d.title:'مستند')}if(o.op==='decision'){var h=getBy('hearings',o.hearing_id),c=h&&getBy('cases',h.case_id);return'قرار جلسة '+(h?fmtDate(h.date):'')+(c?' — '+c.subject:'')}var m={POST:'إضافة',PUT:'تعديل',DELETE:'حذف'}[o.method]||'',coll=collFor(String(o.path||'').replace(/\/@/g,'/'));var n={clients:'موكل',cases:'قضية',hearings:'جلسة',appointments:'موعد',tasks:'مهمة',documents:'مستند',payments:'عملية مالية',deadlines:'ميعاد',adminwork:'شغل إداري',notices:'إعلان',session_secretaries:'سكرتير',templates:'نموذج',case_stages:'درجة',poas:'توكيل'}[coll]||'';return(m+' '+n).trim()||'تعديل'}
