  if(detailTab==='documents')body+=(can('docs.write')?'<button class="primary block" data-add-document="'+c.id+'">رفع مستند</button><br>':'')+(ds.length?ds.map(documentCard).join(''):empty('لا توجد مستندات'));
  if(detailTab==='tasks')body+=(can('tasks.write')?'<button class="primary block" data-add-related="tasks:'+c.id+'">إضافة مهمة</button><br>':'')+(ts.length?ts.map(taskCard).join(''):empty('لا توجد مهام'));
  if(detailTab==='finance')body+=(can('finance.write')?'<button class="primary block" data-add-related="payments:'+c.id+'">إضافة عملية مالية</button><br>':'')+(ps.length?ps.map(paymentCard).join(''):empty('لا توجد عمليات مالية'));
