function render(){if(sheet)return;if(!DK){if(window.MZFull)MZFull.hide();if(readLock())return renderLock();if(lsGet('t'))return renderSetPin({migrate:true});return renderPair()}if(!T)return renderPair();if(!pack){app.innerHTML=header()+'<main class="content">'+noteList()+'<div class="empty"><b>'+(syncing?'جاري تنزيل بيانات المكتب…':'بيانات المكتب لم تصل بعد')+'</b>'+esc(syncErr||'اتصل بالإنترنت واضغط مزامنة')+'<div class="actions"><button class="primary block" data-sync>مزامنة الآن</button></div></div></main>'+nav();return}if(pack.until&&Date.now()>pack.until){app.innerHTML=header()+'<main class="content"><div class="note red">انتهت صلاحية النسخة المحلية لحماية بيانات المكتب. اتصل بالإنترنت وحدّث التطبيق.</div><button class="primary block" data-sync>تحديث الآن</button></main>'+nav();return}if(pack.full&&window.MZFull&&!legacyView&&MZFull.render())return;if(window.MZFull)MZFull.hide();app.innerHTML=header()+'<main class="content">'+(pack.full?'<div class="note">ده سجل المزامنة. <button class="sm" data-full-back>رجوع لميزان</button></div>':'')+noteList()+renderPage()+'</main>'+nav();watermark();bindSearch()}
function bindSearch(){var i=document.querySelector('[data-search]');if(!i)return;var timer;i.oninput=function(){q=i.value;clearTimeout(timer);var pos=i.selectionStart;timer=setTimeout(function(){render();var n=document.querySelector('[data-search]');if(n){n.focus();n.setSelectionRange(pos,pos)}},180)}}
function watermark(){var old=document.querySelector('.wm');if(old)old.remove();if(!pack||!T)return;var text=(pack.user||'')+' · '+(T.d||'')+' · '+new Date().toLocaleDateString('ar-EG'),svg='<svg xmlns="http://www.w3.org/2000/svg" width="340" height="210"><text x="10" y="115" transform="rotate(-24 160 100)" font-family="Tahoma" font-size="13" fill="#777" fill-opacity=".12">'+esc(text)+'</text></svg>',d=document.createElement('div');d.className='wm';d.style.backgroundImage='url("data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg)+'")';document.body.appendChild(d)}
function renderPair(code,msg){sheet=false;var standalone=matchMedia&&matchMedia('(display-mode: standalone)').matches||navigator.standalone,ios=/iPhone|iPad|iPod/.test(navigator.userAgent);app.innerHTML='<div class="pair"><div class="pair-brand"><img src="icon-192.png"><h1>ميزان</h1><div>إدارة مكتب المحاماة</div></div><div class="pair-card">'+(msg?'<div class="note red">'+esc(msg)+'</div>':'')+'<h2>ربط الهاتف بالمكتب</h2><p>من برنامج ميزان على الكمبيوتر افتح «موبايلات المحامين»، أضف الجهاز ثم أدخل الكود.</p><div class="field"><label>كود الربط</label><input id="pair-code" class="code" maxlength="13" autocomplete="off" value="'+esc(code||'')+'" placeholder="XXX-XXX-XXX"></div><div id="pair-error" class="error hidden"></div><button id="pair-go" class="primary block" style="margin-top:14px">التالي: اختار رمز الفتح</button>'+(!standalone?'<div class="install"><b>لتثبيت التطبيق:</b> '+(ios?'من Safari اختر مشاركة ثم «إضافة إلى الشاشة الرئيسية».':'من قائمة Chrome اختر «تثبيت التطبيق».')+'</div>':'')+'<div class="hint">الكود صالح لمرة واحدة. كل البيانات تنتقل مشفرة وتخضع لصلاحيات المستخدم.</div></div>'+(window.MZFull?MZFull.pairExtra():'')+'</div>';var inp=document.getElementById('pair-code');inp.oninput=function(){var c=normCode(inp.value).slice(0,9);inp.value=c.replace(/(.{3})(?=.)/g,'$1-')};document.getElementById('pair-go').onclick=function(){var e=document.getElementById('pair-error');try{if(window.MZFull&&MZFull.isActivation(inp.value))throw new Error('ده كود تفعيل مش كود ربط. لو معندكش كمبيوتر اختار «الموبايل ده هو مكتبي» تحت، وكود التفعيل بيتكتب بعد ما تبدأ');renderSetPin({code:validCode(inp.value)})}catch(x){e.textContent=x.message;e.classList.remove('hidden')}};if(window.MZFull)MZFull.bindPair();}

