async function shrinkImage(file){if(!/^image\/(jpeg|jpg|png|webp|heic|heif)$/i.test(file.type||''))return null;try{var img;if(window.createImageBitmap)img=await createImageBitmap(file);else img=await new Promise(function(res,rej){var u=URL.createObjectURL(file),im=new Image();im.onload=function(){res(im)};im.onerror=rej;im.src=u});var w=img.width,h=img.height,k=Math.min(1,2000/Math.max(w,h));if(!w||!h)return null;var c=document.createElement('canvas');c.width=Math.round(w*k);c.height=Math.round(h*k);var g=c.getContext('2d');g.fillStyle='#fff';g.fillRect(0,0,c.width,c.height);g.drawImage(img,0,0,c.width,c.height);var blob=await new Promise(function(r){c.toBlob(r,'image/jpeg',0.8)});if(!blob||(blob.size>=file.size&&/jpe?g|png|webp/i.test(file.type)))return null;return{bytes:new Uint8Array(await blob.arrayBuffer()),name:String(file.name||'photo').replace(/\.[^.]+$/,'')+'.jpg',mime:'image/jpeg'}}catch(e){return null}}
