// ===== قفل التطبيق: رمز 4–6 أرقام + بصمة/وجه =====
function readLock(){try{return JSON.parse(lsGet('lock')||'null')}catch(e){return null}}
function writeLock(l){lsSet('lock',l?JSON.stringify(l):null)}
function fails(){return Number(lsGet('fails')||0)}
async function pinKey(pin,salt,it){var k=await crypto.subtle.importKey('raw',enc8.encode(String(pin)),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt:salt,iterations:it,hash:'SHA-256'},k,{name:'AES-GCM',length:256},false,['encrypt','decrypt'])}
function useDK(raw){return crypto.subtle.importKey('raw',raw,'AES-GCM',false,['encrypt','decrypt']).then(function(k){raw.fill(0);DK=k;return k})}
function validPin(p){return/^\d{4,6}$/.test(String(p||''))}
async function createLock(pin,keepRaw){if(!validPin(pin))throw new Error('الرمز لازم يكون من 4 لـ 6 أرقام');var raw=keepRaw||crypto.getRandomValues(new Uint8Array(32)),salt=crypto.getRandomValues(new Uint8Array(16)),k=await pinKey(pin,salt,PIN_ITER);var w=await gcmEnc(k,raw);writeLock({v:1,salt:bytesToB64(salt),it:PIN_ITER,w:bytesToB64(w)});lsSet('fails',null);await useDK(raw)}
async function unwrapPin(pin){var l=readLock();if(!l)throw new Error('مفيش قفل');var k=await pinKey(pin,b64ToBytes(l.salt),l.it||PIN_ITER);return gcmDec(k,b64ToBytes(l.w))}
async function unlockPin(pin){var raw;try{raw=await unwrapPin(pin)}catch(e){var n=fails()+1;lsSet('fails',String(n));if(n>=MAX_FAILS){await wipe('اتمسحت بيانات ميزان من الموبايل بعد '+MAX_FAILS+' محاولات غلط — اطلب كود ربط جديد من مدير المكتب');return false}throw new Error('رمز غلط — باقي '+(MAX_FAILS-n)+' محاولة قبل ما البيانات تتمسح')}lsSet('fails',null);await useDK(raw);heldDK=DK;await afterUnlock();return true}
function bioSupported(){return!!(window.PublicKeyCredential&&navigator.credentials&&window.isSecureContext)}
async function prfKey(out){var k=await crypto.subtle.importKey('raw',new Uint8Array(out),'HKDF',false,['deriveKey']);return crypto.subtle.deriveKey({name:'HKDF',hash:'SHA-256',salt:PRF_SALT,info:enc8.encode('mizan-dk-wrap')},k,{name:'AES-GCM',length:256},false,['encrypt','decrypt'])}
async function enableBio(pin){var raw=await unwrapPin(pin).catch(function(){throw new Error('رمز غلط')});var cred=await navigator.credentials.create({publicKey:{challenge:crypto.getRandomValues(new Uint8Array(32)),rp:{name:'ميزان'},user:{id:crypto.getRandomValues(new Uint8Array(16)),name:'mizan-'+(T&&T.i||''),displayName:'ميزان — '+(T&&T.u||'')},pubKeyCredParams:[{type:'public-key',alg:-7},{type:'public-key',alg:-257}],authenticatorSelection:{authenticatorAttachment:'platform',userVerification:'required',residentKey:'preferred'},timeout:60000,extensions:{prf:{eval:{first:PRF_SALT}}}}});if(!cred)throw new Error('ماتفعّلتش');var ext=cred.getClientExtensionResults&&cred.getClientExtensionResults()||{},out=ext.prf&&ext.prf.results&&ext.prf.results.first,l=readLock(),id=bytesToB64(new Uint8Array(cred.rawId));
  if(!out&&ext.prf&&ext.prf.enabled){try{var a=await bioAssert(id);out=a.out}catch(e){}}
  l.bio={id:id,prf:!!out};if(out)l.bio.w=bytesToB64(await gcmEnc(await prfKey(out),raw));raw.fill(0);writeLock(l);return l.bio.prf}
async function bioAssert(id){var a=await navigator.credentials.get({publicKey:{challenge:crypto.getRandomValues(new Uint8Array(32)),allowCredentials:[{type:'public-key',id:b64ToBytes(id)}],userVerification:'required',timeout:60000,extensions:{prf:{eval:{first:PRF_SALT}}}}});if(!a||bytesToB64(new Uint8Array(a.rawId))!==id)throw new Error('البصمة ماتطابقتش');var ext=a.getClientExtensionResults&&a.getClientExtensionResults()||{};return{out:ext.prf&&ext.prf.results&&ext.prf.results.first}}
async function unlockBio(){var l=readLock();if(!l||!l.bio)throw new Error('البصمة مش مفعّلة');var a=await bioAssert(l.bio.id);
  if(l.bio.prf){if(!a.out)throw new Error('الموبايل مارجّعش مفتاح البصمة — افتح بالرمز');var raw=await gcmDec(await prfKey(a.out),b64ToBytes(l.bio.w));await useDK(raw);heldDK=DK}
  else{if(!heldDK)throw new Error('ادخل الرمز مرة الأول — البصمة على الموبايل ده بتفتح بس بعد أول فتح بالرمز');DK=heldDK}
  lsSet('fails',null);await afterUnlock()}
function lock(){if(!DK&&!T)return;if(window.MZFull)MZFull.unmount();if(sheet){var x=document.querySelector('.sheet');if(x)x.remove();sheet=false}var l=readLock();if(!(l&&l.bio&&!l.bio.prf))heldDK=null;DK=null;T=null;pack=null;outbox=[];notes=[];downloads=[];renderLock()}
async function loadState(){T=await sGet('T',null);pack=await sGet('pack',null);outbox=await sGet('outbox',[]);notes=await sGet('notes',[]);downloads=await sGet('downloads',[]);lastSync=await kvGet('last',0);await migrateOutbox()}
// 2.3.2 ⇒ 2.3.3: رفع قديم كان مستني جوه رسالة واحدة ⇒ يتحوّل لرفع على أجزاء
async function migrateOutbox(){var changed=false,list=outbox.slice();for(var i=0;i<list.length;i++){var o=list[i];if(o.op==='mutate'&&o.method==='POST'&&o.path==='/api/documents'&&o.body&&typeof o.body.data==='string'){var bytes=b64ToBytes(o.body.data),b=Object.assign({},o.body);delete b.data;var id=o.uid,hash=hex(await crypto.subtle.digest('SHA-256',bytes));await sSet('f:'+id,bytes,true);outbox[outbox.indexOf(o)]={uid:id,op:'upload',meta:Object.assign(b,{temp:o.temp||b.temp||tempId(),size:bytes.length}),size:bytes.length,sha:hash,chunk:CHUNK,n:Math.max(1,Math.ceil(bytes.length/CHUNK)),next:0,resend:[],tries:0};changed=true}}if(changed)await saveState()}
async function afterUnlock(){lastAct=Date.now();await loadState();if(!T){await wipe('بيانات الربط مش موجودة — اطلب كود جديد');return}legacyView=false;render();if(!T.standalone&&!T.h3&&!DEMO)send({t:'hello',ua:navigator.userAgent.slice(0,120),at:Date.now(),v:APP_V,full:1}).then(function(){T.h3=1;return saveState()}).then(function(){sync(true)}).catch(function(){});if(!DEMO)sync(false)}
