function renderSetPin(opt){sheet=false;opt=opt||{};app.innerHTML=lockShell(opt.change?'رمز جديد':'اختار رمز لفتح التطبيق',opt.migrate?'حماية جديدة: بيانات المكتب هتتشفّر بالرمز ده':'الرمز بيحمي بيانات المكتب لو الموبايل ضاع',(opt.change?'<div class="field"><label>الرمز الحالي</label>'+pinInput('pin-old')+'</div>':'')+'<div class="field"><label>الرمز (4 لـ 6 أرقام)</label>'+pinInput('pin-a')+'</div><div class="field"><label>اكتبه تاني</label>'+pinInput('pin-b')+'</div><div id="pin-err" class="error hidden"></div><button id="pin-set" class="primary block" style="margin-top:12px">'+(opt.code?'حفظ الرمز وربط الموبايل':opt.solo?'حفظ الرمز وابدأ':'حفظ الرمز')+'</button>'+(opt.change||opt.code||opt.solo?'<button id="pin-back" class="secondary block" style="margin-top:8px">رجوع</button>':'')+'<div class="hint">مفيش حد يقدر يرجّعلك الرمز. لو نسيته: مدير المكتب يعمل «ربط تاني». 10 محاولات غلط بتمسح البيانات من الموبايل. الأفضل 6 أرقام.</div>');
  var a=document.getElementById('pin-a'),b=document.getElementById('pin-b'),err=document.getElementById('pin-err'),go=document.getElementById('pin-set');(document.getElementById('pin-old')||a).focus();
  var back=document.getElementById('pin-back');if(back)back.onclick=function(){if(opt.code||opt.solo)renderPair(opt.code||'');else render()};
  go.onclick=async function(){err.classList.add('hidden');if(!validPin(a.value)){err.textContent='الرمز لازم يكون من 4 لـ 6 أرقام';err.classList.remove('hidden');return}if(/^(\d)\1+$/.test(a.value)||'0123456789'.indexOf(a.value)>=0||'9876543210'.indexOf(a.value)>=0){err.textContent='الرمز سهل قوي — اختار أرقام مش متكررة ولا متسلسلة';err.classList.remove('hidden');return}if(a.value!==b.value){err.textContent='الرمزين مش زي بعض';err.classList.remove('hidden');return}go.disabled=true;go.textContent='جاري الحفظ…';
    try{if(opt.code){await pair(opt.code,a.value);return}if(opt.solo){await MZFull.startSolo(a.value,opt.restore);return}
      if(opt.change){var raw=await unwrapPin(document.getElementById('pin-old').value).catch(function(){throw new Error('الرمز الحالي غلط')});var l0=readLock();await createLock(a.value,raw);heldDK=DK;if(l0&&l0.bio)note('اتغير الرمز. فعّل البصمة تاني من الإعدادات','green');else note('اتغير الرمز','green');return}
      if(opt.migrate){var t=JSON.parse(lsGet('t')||'null'),pk=await kvGet('pack',null),ob=await kvGet('outbox',[]),nt=await kvGet('notes',[]);await createLock(a.value);heldDK=DK;T=t;pack=pk;outbox=Array.isArray(ob)?ob:[];notes=Array.isArray(nt)?nt:[];downloads=[];await migrateOutbox();await saveState();lsSet('t',null);await afterUnlock();return}}
    catch(x){if((opt.code||opt.solo)&&!T){writeLock(null);DK=null;return renderPair(opt.code||'',x.message)}err.textContent=x.message;err.classList.remove('hidden');go.disabled=false;go.textContent='حفظ الرمز'}}}
function bioDialog(){sheet=true;app.insertAdjacentHTML('beforeend','<section class="sheet"><div class="sheet-head"><h2>تفعيل البصمة / الوجه</h2><button class="icon-btn" data-close-sheet>✕</button></div><div class="sheet-body"><div class="field"><label>ادخل الرمز الأول</label>'+pinInput('bio-pin')+'</div><div id="form-error" class="error hidden"></div><div class="form-actions"><button class="primary" id="bio-save">تفعيل</button><button class="secondary" data-close-sheet>إلغاء</button></div><div class="hint">لو الموبايل بيدعم فك التشفير بالبصمة (PRF) البصمة بتفتح لوحدها. لو مش بيدعم، البصمة بتفتح بس بعد ما تدخل الرمز مرة من ساعة ما فتحت التطبيق — وأول فتح بعد ما التطبيق يتقفل خالص لازم بالرمز.</div></div></section>');document.getElementById('bio-save').onclick=async function(){var e=document.getElementById('form-error'),b=this;b.disabled=true;try{var prf=await enableBio(document.getElementById('bio-pin').value);closeSheet();note(prf?'البصمة اتفعّلت ✓':'البصمة اتفعّلت ✓ — على الموبايل ده بتفتح بعد أول فتح بالرمز بس','green')}catch(x){e.textContent=x.name==='NotAllowedError'?'اتلغت':x.message;e.classList.remove('hidden');b.disabled=false}}}

